-- Staff, women and Saudi count by branch (cost-centre prefix of the current job). Columns: br, n, fem, saudi
-- Tie: sum(n) = active staff (385 at Al Faihaa, 12 Oct 2026).
SELECT (CASE WHEN x.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(x.ORG,3,1) ELSE SUBSTR(x.ORG,1,2) END) BR, COUNT(*) N, SUM(CASE WHEN x.G='F' THEN 1 ELSE 0 END) FEM, SUM(CASE WHEN x.NAT={SAUDI} THEN 1 ELSE 0 END) SAUDI FROM (SELECT m.sex G, m.nationality_code NAT, (SELECT MAX(t.ORGANIZATION_NO) FROM {P}PS_STAFF_INTERNAL_TRANSFERS t WHERE t.STAFF_ID=c.STAFF_ID AND t.CURRENT_JOB='Y') ORG FROM {P}PS_STAFF_CONTRACT c JOIN {P}STAFF_MASTER m ON m.staff_id=c.STAFF_ID WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y') x GROUP BY (CASE WHEN x.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(x.ORG,3,1) ELSE SUBSTR(x.ORG,1,2) END) ORDER BY 1
